mapper.select:
/* RevertTodoMapper.selectListTotCnt */ SELECT COUNT(*) totcnt FROM ( -- 마스터테이블 SELECT M.INPT_RCP_DT, M.ACTL_FX_REFNO, M.INPT_MST_SRNO, M.TOTALTEXT_AI_INPT_RST_CD, M.ITM_INPT_AI_INPT_RST_CD, M.SAFEWATCH_AI_INPT_RST_CD, M.INPT_ATMC_BIZ_DSCD, M.AI_INPT_PROS_CD, M.AI_INPT_ACVT_CD, M.FX_REFNO_SRNO, M.PAPS_RE_SCAN_CMPL_YN, NVL(E.XPBY_COL_CTR_CUCD, I.TDOC_RCP_CUCD) AS XPBY_COL_CTR_CUCD, NVL(E.XPBY_COL_AM,I.TDOC_RCP_AM) AS XPBY_COL_AM, NVL(E.CUS_KORL_NM,I.CUS_KORL_NM) AS CUS_KORL_NM, NVL(E.CSNO, I.CSNO) AS CSNO, (-- DetectionID SELECT MAX(FILT_DTCT_NO) KEEP( DENSE_RANK FIRST ORDER BY AI_INPT_PRG_SRNO DESC ) AS FILT_DTCT_NO FROM CSPD007TL WHERE INPT_MST_SRNO = M.INPT_MST_SRNO ) AS FILT_DTCT_NO -- DetectionID ,( SELECT MAX(CASE WHEN H.AI_INPT_ACVT_CD = '40' THEN '재추출' WHEN H.AI_INPT_ACVT_CD = '70' THEN '재심사' ELSE X.AI_INPT_CMN_CD_NM END) KEEP( DENSE_RANK FIRST ORDER BY H.AI_INPT_PRG_SRNO DESC) AS AI_INPT_CMN_CD_NM FROM CSPD008TH H , CSPD112TI X WHERE H.INPT_MST_SRNO = M.INPT_MST_SRNO AND (H.AI_INPT_ACVT_STS_CD IN ('60', '70', '120') OR H.AI_INPT_ACVT_CD IN ('40', '70')) AND X.AI_INPT_GRP_CD(+) = '300' AND X.AI_INPT_CMN_CD(+) = H.AI_INPT_ACVT_STS_CD ) AS WRR_INFO -- 주의 코드명 ,(--임시저장최종일시 SELECT NVL(MAX(LST_DB_CHG_DTM),'00000000000000000000') FROM ( SELECT LST_DB_CHG_DTM AS LST_DB_CHG_DTM --심사처리시작시각 FROM CSPD005TH WHERE INPT_MST_SRNO = M.INPT_MST_SRNO AND AI_INPT_TPY_SAVE_YN = 'Y'
UNION ALL
SELECT LST_DB_CHG_DTM AS LST_DB_CHG_DTM --심사처리시작시각 FROM CSPD008TH WHERE INPT_MST_SRNO = M.INPT_MST_SRNO AND INPT_MST_SRNO IN (SELECT INPT_MST_SRNO FROM CSPD008TH WHERE INPT_MST_SRNO = M.INPT_MST_SRNO AND AI_INPT_ACVT_STS_CD = '51') ) ) AS SAVE_CHG_DTM ,M.LST_DB_CHG_DTM AS MST_CHG_DTM --마스터최조정벼변경일시 FROM CSPD001TM M , CSPD201TM E -- 수출테이블 , CSPD202TM I -- 수입테이블
WHERE M.AI_INSPE_ENO = #{userId} AND M.PAPS_RE_SCAN_NED_YN IS NULL AND M.AI_INPT_ACVT_CD IN ('80', '90', '150') AND M.ACTL_FX_REFNO = E.FX_ACNO(+) AND M.FX_REFNO_SRNO = E.XPO_CVRG_MK_SQ(+) AND M.ACTL_FX_REFNO = I.FX_ACNO(+) AND M.FX_REFNO_SRNO = I.TDOC_RCP_SRNO(+)
AND M.INPT_MST_SRNO = #{inptMstSrno}
AND M.INPT_ATMC_BIZ_DSCD = #{inptAtmcBizDscd}
AND M.ACTL_FX_REFNO LIKE '%' || UPPER(#{actlFxRefno}) || '%'
AND M.INPT_RCP_DT BETWEEN REPLACE(#{schSdate1}, '-', '') AND REPLACE(#{schEdate1}, '-', '')
) A, CSPD112TI B, -- 공통코드테이블 그룹코드 : 150 = 업무구분코드 CSPD112TI C, -- 공통코드테이블 그룹코드 : 280 = 프로세스코드 CSPD112TI D, -- 공통코드테이블 그룹코드 : 290 = 액티비티코드 CSPD112TI G, -- 공통코드테이블 그룹코드 : 170 = 심사코드, TotalText CSPD112TI H, -- 공통코드테이블 그룹코드 : 170 = 심사코드, 항목심사 CSPD112TI I -- 공통코드테이블 그룹코드 : 170 = 심사코드, SAFEWATCH WHERE B.AI_INPT_GRP_CD(+) = '150' -- 공통코드테이블 그룹코드 : 150 = 업무구분코드 AND A.INPT_ATMC_BIZ_DSCD = B.AI_INPT_CMN_CD(+) AND C.AI_INPT_GRP_CD(+) = '280' -- 공통코드테이블 그룹코드 : 280 = 프로세스코드 AND A.AI_INPT_PROS_CD = C.AI_INPT_CMN_CD(+) AND D.AI_INPT_GRP_CD(+) = '290' -- 공통코드테이블 그룹코드 : 290 = 액티비티코드 AND A.AI_INPT_ACVT_CD = D.AI_INPT_CMN_CD(+) AND G.AI_INPT_GRP_CD(+) = '170' -- 공통코드테이블 그룹코드 : 170 = 심사코드, TotalText AND A.TOTALTEXT_AI_INPT_RST_CD = G.AI_INPT_CMN_CD(+) AND H.AI_INPT_GRP_CD(+) = '170' -- 공통코드테이블 그룹코드 : 170 = 심사코드, 항목심사 AND A.ITM_INPT_AI_INPT_RST_CD = H.AI_INPT_CMN_CD(+) AND I.AI_INPT_GRP_CD(+) = '170' -- 공통코드테이블 그룹코드 : 170 = 심사코드, SAFEWATCH AND A.SAFEWATCH_AI_INPT_RST_CD = I.AI_INPT_CMN_CD(+)
AND A.CSNO = #{aiInptCsno}
